#!/usr/bin/env node
// Writes the grammar and scheme pages from schemes/*.json, and copies llms.txt and llms-full.txt
// into static/. With --check, fails if any generated file is out of date.

import { existsSync, mkdirSync, readFileSync, readdirSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { buildLlms } from "../../scripts/build-llms.mjs";

const docs = join(dirname(fileURLToPath(import.meta.url)), "..");
const repo = join(docs, "..");
const check = process.argv.includes("--check");
const read = (p) => JSON.parse(readFileSync(join(repo, p), "utf8"));
const g = read("schemes/grammar.json");
const ids = readdirSync(join(repo, "schemes"))
  .filter((f) => f.endsWith(".json") && f !== "grammar.json")
  .map((f) => f.replace(/\.json$/, ""))
  .sort();
const schemes = ids.map((id) => read(`schemes/${id}.json`));
const qs = Object.fromEntries([...g.reasons, ...g.scopes].flatMap((x) => x.questions.map((q) => [q.id, q])));
const sits = Object.fromEntries(g.situations.map((s) => [s.id, s]));
const esc = (s) => String(s).replaceAll("|", "\\|").replaceAll("\n", " ").replaceAll("<", "&lt;");
const fm = (o) =>
  `---\n${Object.entries(o)
    .map(([k, v]) => `${k}: ${JSON.stringify(v)}`)
    .join("\n")}\n---\n\n`;
const NOTE = "<!-- Generated by docs/scripts/generate.mjs from schemes/. Do not edit by hand. -->\n\n";

const files = {};

files["docs/grammar/overview.md"] =
  fm({
    sidebar_position: 1,
    title: "Overview",
    description: "The Open DS grammar: reasons, scopes, tokens and the component API, and how answers link.",
  }) +
  NOTE +
  `# The grammar\n\n${g.description}\n\n` +
  g.layers.map((l, i) => `${i + 1}. **${l.id}**: ${l.description}`).join("\n") +
  `\n\n- [Reasons](reasons.md): ${g.reasons.length} groups\n- [Scopes](scopes.md): ${g.scopes.length} groups\n- [Situations](situations.md): ${g.situations.length}\n- [Component API](component-api.md): ${g.component_keys.length} keys\n`;

const groupPage = (title, desc, groups, pos) =>
  fm({ sidebar_position: pos, title, description: desc }) +
  NOTE +
  `# ${title}\n\n${desc}\n\n` +
  groups
    .map(
      (grp) =>
        `## ${grp.title}\n\n${grp.description}\n\n` +
        grp.questions
          .map(
            (q) =>
              `- **${q.text}** ${q.description} Answers: ${q.options.map((o) => o.label).join(" · ")}. \`${q.id}\``,
          )
          .join("\n"),
    )
    .join("\n\n") +
  "\n";

files["docs/grammar/reasons.md"] = groupPage(
  "Reasons",
  "Why a design system exists. Answered before any design decision.",
  g.reasons,
  2,
);
files["docs/grammar/scopes.md"] = groupPage(
  "Scopes",
  "The design decisions. Each answer points back to the reasons that pulled it.",
  g.scopes,
  3,
);
files["docs/grammar/situations.md"] =
  fm({
    sidebar_position: 4,
    title: "Situations",
    description: "The moments where people need to know what to use. Every scheme answers each one.",
  }) +
  NOTE +
  "# Situations\n\nEvery scheme answers each situation with what to use, what not to use, and why.\n\n| Situation | Scope | What it means |\n| --- | --- | --- |\n" +
  g.situations.map((s) => `| ${s.title} | ${s.scope} | ${esc(s.description)} |`).join("\n") +
  "\n";
files["docs/grammar/component-api.md"] =
  fm({
    sidebar_position: 5,
    title: "Component API",
    description: "The shared component keys. Every scheme fills every key; components read only keys.",
  }) +
  NOTE +
  "# Component API\n\nComponents read only these keys. A scheme changes how they look by pointing a key at a different decision. The CSS variable is the key with `/` replaced by `-`.\n\n| Key | What it controls | Default decision |\n| --- | --- | --- |\n" +
  g.component_keys.map((k) => `| \`${k.id}\` | ${esc(k.description)} | \`${k.default}\` |`).join("\n") +
  "\n";

files["docs/schemes/index.md"] =
  fm({
    sidebar_position: 0,
    title: "All schemes",
    description: "The five Open DS schemes, what each is for, and what to avoid it for.",
  }) +
  NOTE +
  "# Schemes\n\n| Scheme | For | Avoid when |\n| --- | --- | --- |\n" +
  schemes.map((s) => `| [${s.name}](${s.id}.md) | ${esc(s.summary)} | ${esc(s.ai.avoid_when)} |`).join("\n") +
  "\n";

schemes.forEach((s, i) => {
  const answer = (a) => qs[a.question].options.find((o) => o.id === a.option).label;
  const section = (kind) =>
    s.answers
      .filter(
        (a) =>
          qs[a.question] &&
          [...(kind === "reason" ? g.reasons : g.scopes)].some((grp) => grp.questions.some((q) => q.id === a.question)),
      )
      .map(
        (a) =>
          `- **${qs[a.question].text}** ${answer(a)}. ${a.why}${a.because.length ? ` Because: ${a.because.map((b) => `${qs[b].text} ${answer(s.answers.find((x) => x.question === b))}`).join("; ")}.` : ""}`,
      )
      .join("\n");
  files[`docs/schemes/${s.id}.md`] =
    fm({ sidebar_position: i + 1, title: s.name, description: s.summary }) +
    NOTE +
    `# ${s.name}\n\n${s.description}\n\n- **Use when:** ${s.ai.use_when}\n- **Avoid when:** ${s.ai.avoid_when}\n- **Examples:** ${s.ai.example_products.join(", ")}\n- **Themes:** ${s.themes.map((t) => t.id).join(", ")}\n- **Status:** ${s.status}\n\n` +
    `## The work it serves\n\n${s.scenarios.map((x) => `- ${x}`).join("\n")}\n\n` +
    `## Voice and tone\n\n${s.voice.summary}\n\n${s.voice.principles.map((p) => `- ${p}`).join("\n")}\n\n| Context | Tone | Example |\n| --- | --- | --- |\n` +
    Object.entries(s.voice.tone)
      .map(([k, v]) => `| ${k} | ${esc(v)} | ${esc(s.voice.examples.find((e) => e.context === k)?.text ?? "")} |`)
      .join("\n") +
    `\n\nUse: ${s.voice.words.use.join(", ")}. Avoid: ${s.voice.words.avoid.join(", ")}.\n\n` +
    `## Reasons\n\n${section("reason")}\n\n## Design decisions\n\n${section("scope")}\n\n` +
    `## When to use\n\n| Situation | Use | Not | Why |\n| --- | --- | --- | --- |\n${s.usage.map((u) => `| ${sits[u.situation].title} | ${esc(u.use)} | ${esc(u.not)} | ${esc(u.why)} |`).join("\n")}\n\n` +
    `## Deploy it\n\n\`\`\`bash\nnode cli/bin/open-ds.js init ${s.id} --dir ./my-app\n\`\`\`\n`;
});

const llms = buildLlms(repo);
files["static/llms.txt"] = llms["llms.txt"];
files["static/llms-full.txt"] = llms["llms-full.txt"];

let stale = [];
for (const [rel, text] of Object.entries(files)) {
  const path = join(docs, rel);
  if (check) {
    if (!existsSync(path) || readFileSync(path, "utf8") !== text) stale.push(rel);
    continue;
  }
  mkdirSync(dirname(path), { recursive: true });
  writeFileSync(path, text);
}
if (check && stale.length) {
  console.error(`Out of date: ${stale.join(", ")}. Run: pnpm --dir docs generate`);
  process.exit(1);
}
console.log(check ? "Generated docs are current." : `Wrote ${Object.keys(files).length} files.`);
